    {"rust4pm", "import_xes_path", "import_xes_path", "host_helper"},
    {"rust4pm", "import_xes_gz", "import_xes_gz", "wire"},
    {"rust4pm", "import_pnml", "import_pnml", "wire"},
    {"rust4pm", "import_pnml_path", "import_pnml_path", "host_helper"},
