    {"rust4pm", "ocel_new", "ocel_new", "wire"},
    {"rust4pm", "ocel_add_event_type", "ocel_add_event_type", "wire"},
    {"rust4pm", "ocel_add_object_type", "ocel_add_object_type", "wire"},
