    {"rust4pm", "xes_to_ocel", "xes_to_ocel", "wire"},
    {"rust4pm", "import_ocel_json", "import_ocel_json", "wire"},
    {"rust4pm", "ocel_to_xml", "ocel_to_xml", "wire"},
