    {"ferroplan", "session_set_fact", "session_set_fact", "wire"},
    {"ferroplan", "session_set_timed_fact", "session_set_timed_fact", "wire"},
    {"ferroplan", "session_observe", "session_observe", "wire"},
    {"ferroplan", "session_goal_met", "session_goal_met", "wire"},
    {"ferroplan", "session_fact", "session_fact", "wire"},
